      },
      {
        "id": "growth_dynamics_considered",
        "category": "Methodology",
        "label": "Market growth dynamics considered",
        "notes": "The analysis is scoped to current-year figures and does not include an explicit market CAGR or growth-rate assumption. One source notes that FSM software adoption is projected to grow from roughly 48% to 70% of firms by 2027, but this is embedded in the serviceability factor rather than surfaced as a standalone growth assumption. Investors will typically ask about market trajectory \u2014 citing the FSM software CAGR (available from IBISWorld or Global Market Insights) and noting whether the market is expanding would strengthen the narrative."
      }
    ]
  },
  "validation": {
    "status": "valid",
    "errors": []
  },
  "metadata": {
    "run_id": "20260924T224153Z"
  }
}

